import distinctionsJson from '../data/nostos/distinctions.json';
import edgesJson from '../data/nostos/edges.json';
import etymologiesJson from '../data/nostos/etymologies.json';
import imagesJson from '../data/nostos/images.json';
import libraryJson from '../data/nostos/library.json';
import linesJson from '../data/nostos/lines.json';
import metaJson from '../data/nostos/meta.json';
import mythsJson from '../data/nostos/myths.json';
import practicesJson from '../data/nostos/practices.json';
import questionsJson from '../data/nostos/questions.json';
import quizJson from '../data/nostos/quiz.json';
import sequencesJson from '../data/nostos/sequences.json';
import talksJson from '../data/nostos/talks.json';
import truefalseJson from '../data/nostos/truefalse.json';
import writingsJson from '../data/nostos/writings.json';
