// ---------- Types (the shapes in the data files; see tasks/nostos.md, "The content") ----------

export type GroupId = 'path' | 'soul' | 'ethics' | 'cosmos' | 'ways' | 'thinkers' | 'gods';
export interface Group {
  id: GroupId;
  label: string;
  sub: string;
}
/** A place in a talk: the talk's YouTube id and where in it ("53:08", "1:08:54") */
export interface TalkRef {
  id: string;
  t?: string | number;
  note?: string;
}
export interface Concept {
  id: string;
  label: string;
  greek?: string;
  translit?: string;
  kind?: string;
  group: GroupId;
  /** what it means in her teaching */
  take: string;
  /** other angles */
  more?: string[];
  /** 1 to 5 */
  weight: number;
  /** mentions across the transcripts (loose: see tasks/nostos.md) */
  freq: number;
  /** freq estimated from weight, not counted */
  est?: boolean;
  talks: TalkRef[];
  /** connections she makes herself */
  links: { to: string; why: string }[];
}
export interface Edge {
  a: string;
  b: string;
  /** she links them herself */
  her: boolean;
  /** how often she discusses them within the same five minutes */
  co: number;
  npmi: number;
  why?: string;
}
export interface Talk {
  id: string;
  title: string;
  en: string;
  channel: string;
  dur: string;
  lang: string;
  status: string;
}
export interface Writing {
  id: string;
  title: string;
  title_en?: string;
  venue?: string;
  year?: number | string;
  lang?: string;
  kind?: string;
  url?: string;
  readable?: boolean;
  summary?: string;
  key_ideas?: string[];
  terms?: string[];
  concepts?: string[];
}
/** Items reconstructed from garbled captions carry uncertain: true (show it quietly, never hide it) */
interface FromTalk {
  talk?: string;
  t?: string | number;
  uncertain?: boolean;
}
export interface QuizItem extends FromTalk {
  q: string;
  a: string;
  wrong: string[];
  explain?: string;
}
export interface TrueFalseItem extends FromTalk {
  s: string;
  true: boolean;
  explain?: string;
}
export interface Sequence extends FromTalk {
  id: string;
  title: string;
  steps: string[];
  note?: string;
}
export interface Myth extends FromTalk {
  id: string;
  title: string;
  beats: { beat: string; reading: string }[];
}
export interface Etymology extends FromTalk {
  word: string;
  translit?: string;
  parts: { part: string; meaning: string }[];
  reading: string;
  /** hers: her own reading (some scholars dispute it); standard; disputed */
  status: 'hers' | 'standard' | 'disputed' | string;
}
export interface Distinction extends FromTalk {
  a: string;
  a_gloss: string;
  b: string;
  b_gloss: string;
  point?: string;
}
export interface Practice extends FromTalk {
  title: string;
  steps: string[];
  why?: string;
}
export interface ImageItem extends FromTalk {
  image: string;
  meaning: string;
}
export interface Question extends FromTalk {
  q: string;
}
export interface Line extends FromTalk {
  text: string;
}
export interface Excerpt {
  ref: string;
  label?: string;
  greek?: string;
  translation: string;
  translator?: string;
  source_url?: string;
  her_reading?: string;
  talk?: string;
  t?: string | number;
}
export interface Work {
  id: string;
  title: string;
  author: string;
  greek_title?: string;
  why_she_reads_it: string;
  talks?: TalkRef[] | string[];
  weight?: number;
  excerpts: Excerpt[];
  next_step?: string;
}
/** A star on the map: its place, its size, and how strongly it is tied to others */
export interface Star {
  id: string;
  x: number;
  y: number;
  r: number;
}

// ---------- Switches ----------

/** The two activities that need Claude (Socratic sparring, Teach it back) stay hidden until Maria
 *  decides on the server function they need (tasks/nostos.md, "Claude-powered activities"). */
export const nostosFlags = { claude: false };

// ---------- The data ----------

export const meta = metaJson as { about: string; transcribedTalks: number; groups: Group[] };
export const groups = meta.groups;
export const concepts = conceptsJson as Concept[];
export const edges = edgesJson as Edge[];
export const talks = talksJson as Talk[];
export const writings = writingsJson as Writing[];
export const quiz = quizJson as QuizItem[];
export const truefalse = truefalseJson as TrueFalseItem[];
export const sequences = sequencesJson as Sequence[];
export const myths = mythsJson as Myth[];
export const etymologies = etymologiesJson as Etymology[];
export const distinctions = distinctionsJson as Distinction[];
export const practices = practicesJson as Practice[];
export const images = imagesJson as ImageItem[];
export const questions = questionsJson as Question[];
export const lines = linesJson as Line[];
export const library = libraryJson as { works: Work[]; reading_path: string[] };

// ---------- Look-ups ----------

const conceptMap = new Map(concepts.map((c) => [c.id, c]));
const talkMap = new Map(talks.map((t) => [t.id, t]));

export const conceptById = (id: string) => conceptMap.get(id);
export const talkById = (id: string) => talkMap.get(id);
export const groupById = (id: string) => groups.find((g) => g.id === id);

/** Every link touching a concept, strongest first, with the concept at the other end */
export function edgesFor(id: string) {
  return edges
    .filter((e) => (e.a === id || e.b === id) && conceptMap.has(e.a) && conceptMap.has(e.b))
    .map((e) => ({ ...e, other: (e.a === id ? e.b : e.a) as string, score: edgeScore(e) }))
    .sort((x, y) => y.score - x.score);
}

/** The prototype's link strength: her own link 0.6, npmi x 2.2, log1p(co) x 0.18, (weights) / 18 */
export function edgeScore(e: Edge) {
  const w = (id: string) => conceptMap.get(id)?.weight || 2;
  return (e.her ? 0.6 : 0) + (e.npmi || 0) * 2.2 + Math.log1p(e.co || 0) * 0.18 + (w(e.a) + w(e.b)) / 18;
}

/** Etymologies whose word is the concept's Greek word (accents and case ignored) */
export function rootsFor(concept: Concept) {
  if (!concept.greek) return [];
  const key = plain(concept.greek);
  return etymologies.filter((e) => plain(e.word) === key);
}

/** Everything drawn from one talk, for the Sources page and "where she says it" */
export function itemsForTalk(id: string) {
  const from = <T extends FromTalk>(list: T[]) => list.filter((item) => item.talk === id);
  return {
    concepts: concepts.filter((c) => c.talks.some((t) => t.id === id)),
    quiz: from(quiz),
    truefalse: from(truefalse),
    sequences: from(sequences),
    myths: from(myths),
    etymologies: from(etymologies),
    distinctions: from(distinctions),
    practices: from(practices),
    images: from(images),
    questions: from(questions),
    lines: from(lines),
  };
}

/** Seconds from a place in a talk: 95, "1:35" or "1:01:35" */
export function seconds(t?: string | number) {
  if (t === undefined || t === '') return 0;
  if (typeof t === 'number') return Math.floor(t);
  const parts = t.split(':').map(Number);
  return parts.every((n) => !Number.isNaN(n)) ? parts.reduce((total, n) => total * 60 + n, 0) : 0;
}

/** A YouTube link to a moment in a talk */
export const talkUrl = (id: string, t?: string | number) => {
  const s = seconds(t);
  return `https://www.youtube.com/watch?v=${id}${s ? `&t=${s}s` : ''}`;
};

/** A talk's name for a list: its English title, without the hash some titles start with */
export const talkName = (id: string) => {
  const talk = talkMap.get(id);
  return talk ? (talk.en || talk.title).replace(/^#\s*/, '') : id;
};

/** A concept's label without its bracketed aside or second clause, for the map */
export const shortLabel = (label: string) => label.replace(/\s*\(.*?\)/g, '').replace(/,.*$/, '');

/** Text without accents, breathings or case, for search and matching (σπήλαιον = σπηλαιον = ΣΠΉΛΑΙΟΝ) */
export const plain = (text: string) =>
  text
    .normalize('NFD')
    .replace(/\p{M}/gu, '')
    .toLocaleLowerCase('el')
    .replace(/ς/g, 'σ');

// ---------- The bookshelf ----------

/** The books on the shelf, in the order they stand: by author, as in the prototype */
export const shelf = library.works.slice().sort((a, b) => (a.author || '').localeCompare(b.author || ''));

/** The ideas on the map that a book threads into: its author when the author is a star, and any idea
 *  named in what is said about the book (the prototype's conceptsFor), most mentioned first */
export function conceptsForWork(w: Work) {
  const text = [w.title, w.author, w.why_she_reads_it, ...w.excerpts.map((e) => `${e.her_reading ?? ''} ${e.label ?? ''}`)]
    .join(' ')
    .toLowerCase();
  const ids = new Set<string>();
  const authors: Record<string, string> = {
    plato: 'plato',
    heraclitus: 'heraclitus',
    homer: 'homer',
    plotinus: 'plotinus',
    proclus: 'proclus',
    pythagoras: 'pythagoras',
    parmenides: 'parmenides',
    aristotle: 'aristotle',
    orpheus: 'orpheus',
    orphic: 'orpheus',
    empedocles: 'empedocles',
  };
  for (const [word, id] of Object.entries(authors)) if (text.includes(word) && conceptMap.has(id)) ids.add(id);
  for (const c of concepts) {
    if (c.group === 'thinkers') continue;
    const label = c.label.toLowerCase();
    if (label.length > 3 && text.includes(label)) ids.add(c.id);
  }
  return [...ids].sort((a, b) => (conceptMap.get(b)!.freq || 0) - (conceptMap.get(a)!.freq || 0)).slice(0, 10);
}

/** The talks a book comes up in: its own list and those its passages are read in */
export const talksForWork = (w: Work) =>
  [...new Set([...((w.talks ?? []) as (string | TalkRef)[]).map((t) => (typeof t === 'string' ? t : t.id)), ...w.excerpts.map((e) => e.talk)])].filter(
    (id): id is string => !!id && talkMap.has(id),
  );

// ---------- The map (positions from the build-time layout) ----------

const layout = layoutJson as {
  source: string;
  viewBox: [number, number, number, number];
  stars: Record<string, [number, number, number]>;
  core: [string, string][];
};

/** A concept added to the data after the layout was made gets a place near its theme until the
 *  layout is run again (it runs before every build); the dev server says so once. */
const missing = concepts.filter((c) => !layout.stars[c.id]);
if (missing.length) {
  console.warn(`[nostos] ${missing.length} concepts have no place on the map yet: run npm run nostos:layout`);
}

export const mapViewBox = layout.viewBox;
export const stars: Star[] = concepts.map((c, i) => {
  const at = layout.stars[c.id];
  if (at) return { id: c.id, x: at[0], y: at[1], r: at[2] };
  const g = groups.findIndex((group) => group.id === c.group);
  const a = (g / groups.length) * Math.PI * 2 - Math.PI / 2;
  return { id: c.id, x: Math.cos(a) * 540 + (i % 5) * 12, y: Math.sin(a) * 300, r: 6 };
});
/** Each star's three strongest links, the lines the map shows by default */
export const coreLinks = layout.core.filter(([a, b]) => conceptMap.has(a) && conceptMap.has(b));
